SELECT nomme les champs à afficher. FROM nomme la table. WHERE fixe la condition. ORDER BY trie les résultats, et DESC signifie du plus grand au plus petit.

D’autres commandes modifient les données :

INSERT INTO Students (Name, Mark) VALUES ('Wanjiru', 68);
