SELECT na-akpọ aha fields a ga-egosi. FROM na-akpọ aha tebụl. WHERE na-etinye condition (ọnọdụ a na-enyocha). ORDER BY na-ahazi nsonaazụ n’usoro, DESC pụtakwara na nke kachasị ukwuu ga-ebu ụzọ.

